from pathlib import Path
import json,hashlib
B=Path(__file__).parent
old=B/'expanded-v1';qs=json.loads((old/'questions.json').read_text())['questions'];ks=json.loads((old/'answer-key.json').read_text())['answers'];nov=[]
def add(q,a,refs,new):
 i=f'Q{len(qs)+1:02}';qs.append({'id':i,'question':q});ks.append({'id':i,'answer':a,'source_refs':refs});nov.append({'id':i,'new_coverage':new,'source_refs':refs})
add('When an action directly grants a flexible Any Element, may its choice be delayed like an Any space on a Presence track?', 'No. Directly gained flexible Elements must be chosen immediately when gained; passive track Any can wait until later in turn, then is fixed for that turn.', ['FAQ Core: choosing-flexible-elements; .7w4g8p4'], 'Flexible Element selection timing differs by source.')
add('A damaged Dahan leaves a land where it has bonus Health and now its Damage meets its Health. Is it destroyed in the starting land, destination or an in-between space?', 'It is destroyed in the destination. There is no in-between location; it has the starting bonus until arriving, then new Health immediately applies.', ['FAQ Core: if-an-invader-with-health-bonus-and-damage-is-moved-where-is-it-destroyed'], 'Health-change destruction location affects triggers.')
add('When one action removes N Health worth of Invaders based on a count in a land, is the allowance split into N-sized batches? Can separate each-player Health removal allowances be pooled?', 'Single action totals its allowance and may remove any set at or below it, not mandatory batches. Separate each-player removals are separate actions and their allowances cannot be combined.', ['FAQ Core: scaling-removal-of-health-worth-of-invaders'], 'Combined allowance within action versus independent each-player limits.')
add('How are Scapegoats at Terror II and III divided into actions, and what does each level destroy in each land with Towns/Cities?', 'One action per land with Towns/Cities. II destroys one Explorer per Town plus two per City. III destroys all Explorers then one Town per City. Do not split Town/City clauses into independent actions.', ['FAQ Core: scapegoats-action'], 'Fear-card per-land action boundary and ordered effects.')
add('An effect must add two Blight simultaneously but only one remains on Healthy Island. What happens to that remaining Blight, when are immediate flip effects resolved, and when are the two added?', 'Immediately flip, carry the remaining old Blight into the new pool and add printed new pool without setup bonus. Fully resolve immediate flipped-card effects as nested actions before returning to add the two Blight.', ['FAQ Core: .9v5kfqt; one-more-blight-errata'], 'Insufficient simultaneous Blight causes pre-add flip and old-pool carryover.')
add('A Power was used Fast, then is explicitly made Slow before its ordinary Repeat. Which phase does the Repeat use? What if its text explicitly tells you to Repeat immediately?', 'Ordinary Repeat uses most recently assigned speed, so now Slow. Explicit immediate Repeat timing happens immediately after original use regardless of phase.', ['FAQ Core: repeating-powers-with-changed-speeds'], 'Latest speed versus explicit immediate timing.')
add('May Powers and Special Rules measure Range through Ocean as a land when Ocean In Play is active, and does that make all outside edges Coastal?', 'Yes, Powers/Special Rules can measure through active Ocean as land. Coastal remains adjacency to printed Ocean; cliff/outside edges do not become Coastal merely as outside edges.', ['FAQ Core: range-through-ocean','CORE p.13'], 'Active Ocean usable as intervening Range step.')
add('Mists of Oblivion does 1 Damage to each Town/City in its target. Does this automatically destroy healthy buildings? Can Damage boosts count for its destruction-based Fear?', 'No, healthy Towns/Cities survive one Damage unless prior Damage or further effects/thresholds finish them. Boosted Damage belongs to original Power, so actual buildings it destroys with boosts count for its destruction-based Fear.', ['FAQ Core: .bu6odei; is-boosted-damage-from-the-same-source'], 'Conditional bonus not automatic destruction and boosted attribution.')
add('A Power such as Words of Warning makes Dahan deal Ravage Damage earlier than normal. Is that an extra attack in addition to the normal counterattack?', 'No; it changes timing instead of granting an extra attack. Each Dahan still deals Ravage Damage only once.', ['FAQ Core: number-of-counterattacks-when-dahan-counterattack-early'], 'Early Dahan Damage replaces usual counterattack timing.')
add('For outcome checks, how are a Fear Card containing only each-player instructions and one containing a global instruction plus each-player instructions divided into actions?', 'Only each instructions: one action per each (e.g., per player). Mixed global and each instructions: one overall action with nested per-each actions. Complete appropriate action tree before checking outcomes; do not combine independent each-player actions into one.', ['FAQ Core: actions-for-fear-and-event-cards-with-both-each-and-non-each-instructions'], 'Independent per-each trees versus nested mixed-card tree.')
add('If Dahan survive Cast Down into the Briny Deep’s destruction because Infinite Vitality protects them, may they remain on the destroyed board, and does relocating them trigger movement effects?', 'No; clean them up to nearest legal land after action tree. Cleanup is not movement or another action and triggers nothing; if no legal land exists return them to supply as cleanup.', ['FAQ Core: .bu6ocxx; .7w4gdtl'], 'Destroyed-place survivor cleanup as opposed to existing Ocean place.')
D=B/'expanded-v2';D.mkdir(exist_ok=True)
q={**json.loads((old/'questions.json').read_text()),'benchmark_version':'expanded-v2','questions':qs}; k={**json.loads((old/'answer-key.json').read_text()),'benchmark_version':'expanded-v2','answers':ks}
for name,v in [('questions.json',q),('answer-key.json',k),('novelty.json',nov)]:
 p=D/name
 if p.exists():raise RuntimeError(f'Refuse overwrite {p}')
 p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
(D/'question-bank.md').write_text('# Spirit Island expanded bank v2\n\nAll previous IDs, wording and keys preserved.\n\n'+'\n\n'.join(f"## {q['id']}\n\n{q['question']}\n\n**Expected:** {k['answer']}\n\n**Sources:** {'; '.join(k['source_refs'])}" for q,k in zip(qs,ks))+'\n')
(D/'input-manifest.json').write_text(json.dumps({'question_count':len(qs),'prior_version':'expanded-v1','prior_entries_preserved':qs[:89]==json.loads((old/'questions.json').read_text())['questions'] and ks[:89]==json.loads((old/'answer-key.json').read_text())['answers'],'sha256':{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in [D/'questions.json',D/'answer-key.json',old/'questions.json',old/'answer-key.json']},'source_manifest':'../source-manifest.json'},indent=2)+'\n')
print('Expanded-v2 frozen:',len(qs))
